	// Function Engine.Actor.ActivateEventClass (Final, Defined, Simulated)
	bool AActor::ActivateEventClass(class UClass* InClass, class AActor* InInstigator, TArray<class USequenceEvent*>* EventList, TArray<int>* ActivateIndices, bool bTest, TArray<class USequenceEvent*>* ActivatedEvents)
	{
		static class UFunction* fn_ = nullptr;
		if (!fn_) fn_ = detail::FindFunction("Engine.Actor.ActivateEventClass");
		AActor_ActivateEventClass_Params p_{};
		p_.InClass = InClass;
		p_.InInstigator = InInstigator;
		if (EventList) p_.EventList = *EventList;
		if (ActivateIndices) p_.ActivateIndices = *ActivateIndices;
		p_.bTest = bTest ? 1u : 0u;
		if (ActivatedEvents) p_.ActivatedEvents = *ActivatedEvents;
		detail::Call(this, fn_, &p_);
		if (EventList) *EventList = p_.EventList;
		if (ActivateIndices) *ActivateIndices = p_.ActivateIndices;
		if (ActivatedEvents) *ActivatedEvents = p_.ActivatedEvents;
		return p_.ReturnValue != 0;
	}

